const fs = require('node:fs');
const assert = require('node:assert/strict');
const path = require('node:path');
const {JSDOM, VirtualConsole} = require('jsdom');
const bundle = fs.readFileSync(path.resolve(__dirname,'../../src/webui/dist/ohmymeme.js'),'utf8');
const errors=[];
const consoleEvents=new VirtualConsole();
consoleEvents.on('error',(...args)=>errors.push(args.map(String).join(' ')));
consoleEvents.on('jsdomError',e=>errors.push(String(e)));
const dom=new JSDOM('<div id="app-mount"></div>',{url:'http://127.0.0.1:12345/',runScripts:'outside-only',pretendToBeVisual:true,virtualConsole:consoleEvents});
const w=dom.window;
w.matchMedia=()=>({matches:false,addEventListener(){},removeEventListener(){}});
w.ResizeObserver=class{observe(){} disconnect(){}};
w.IntersectionObserver=class{observe(){} disconnect(){}};
w.scrollTo=()=>{};
const item={id:1,filename:'fixture.png',original_name:'Saved WeChat Sticker',name:'Saved WeChat Sticker',width:20,height:20,mime_type:'image/png',file_size:100};
const replies={get_init_data:{memes:[item],tags:[],collections:[{id:1,name:'WeChat',children:[]}],show_startup_animation:false,guide_ok:true},get_settings:{show_startup_animation:false,guide:'ok'},count_memes:1,search_memes:[item],get_tags:[],get_collections:[{id:1,name:'WeChat',children:[]}],check_update:{has_update:false}};
const calls=[];
const api=new Proxy({}, {get(_t,method){return async()=>{calls.push(method);return replies[method]??null;};}});
w.pywebview={api:process.argv[2]==='delayed'?{}:api};
w.addEventListener('unhandledrejection',e=>errors.push(String(e.reason)));
process.on('unhandledRejection',e=>errors.push(String(e)));
w.eval(bundle);
if(process.argv[2]==='delayed')setTimeout(()=>{w.pywebview.api=api;w.dispatchEvent(new w.Event('pywebviewready'));},200);
setTimeout(()=>{
 const card=w.document.querySelector('[data-meme-id="1"][role="button"]');
 const visible=card?.getAttribute('aria-label')===item.name && card.querySelector('img')?.getAttribute('alt')===item.name;
 const result={mode:process.argv[2]||'immediate',visible,calls:[...new Set(calls)],errors};
 console.log(JSON.stringify(result));
 dom.window.close();
 assert.deepEqual(errors, [], 'Startup must not throw interface errors');
 assert(calls.includes('get_init_data'), 'Must read saved data through the real startup path');
 assert(visible,'STARTUP_GALLERY_EMPTY: saved sticker must appear without refresh');
},1600);
